"""matplotlib.backends.backend_mixed — mixed backend stub.

The shim renders every figure through plotly, so this module exists to
satisfy ``from matplotlib.backends.backend_mixed import
FigureCanvasMixed`` imports. Saving uses plotly's native export.
"""

from matplotlib.backends._backend_helpers import (
    _make_canvas, _make_manager, _make_backend,
)


FigureCanvasMixed = _make_canvas('FigureCanvasMixed', 'png')
FigureManagerMixed = _make_manager('FigureManagerMixed')

# Aliases — every backend exposes ``FigureCanvas`` and ``FigureManager``.
FigureCanvas = FigureCanvasMixed
FigureManager = FigureManagerMixed

# Backend class registered with matplotlib's _Backend system.
_BackendStub = _make_backend('_BackendMixed', FigureCanvas, FigureManager)
new_figure_manager = _BackendStub.new_figure_manager
draw_if_interactive = _BackendStub.draw_if_interactive
show = _BackendStub.show


# ─── Added: missing public names (stub classes/funcs) ────────
class MixedModeRenderer:
    """Stub: real matplotlib defines this in the mixed backend."""
    def __init__(self, *args, **kwargs): pass
